// ===== Build Source List =====
// Turns the sources array from Config into one n8n item per source, each
// carrying the Google-News-scoped RSS URL to fetch. No network calls happen
// here — this only prepares data for the HTTP Request node that follows,
// since fetch() is not available inside n8n Code nodes on every instance.

const config = $('Set Configuration Fields').first().json;
const sources = config.sources; // array of { name, domain }

function buildNewsRssUrl(name) {
  const query = `"${name}" AI`;
  return `https://news.google.com/rss/search?q=${encodeURIComponent(query)}&hl=en-IN&gl=IN&ceid=IN:en`;
}

return sources.map(s => ({
  json: {
    name: s.name,
    domain: s.domain,
    rssUrl: buildNewsRssUrl(s.name),
  },
}));

// ===== Parse & Filter Articles =====
// Reads the raw RSS/XML text the "Fetch RSS" HTTP Request node returned for
// each source (one HTTP Request output item per "Build Source List" item, in
// the same order), extracts articles, and applies a light keyword pass and
// the lookback-window filter before the OpenAI call.

const config = $('Set Configuration Fields').first().json;
const lookbackHours = config.lookbackHours || 30;
const cutoff = Date.now() - lookbackHours * 60 * 60 * 1000;

const AI_TERMS = ['ai', 'artificial intelligence', 'machine learning', 'genai',
  'generative ai', 'llm', 'agentic', 'ml model', 'ml-powered', 'ml powered'];

function containsAny(haystack, terms) {
  const h = haystack.toLowerCase();
  return terms.some(t => h.includes(t));
}

function stripHtml(str) {
  if (!str) return '';
  return str.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
}

function decodeEntities(str) {
  if (!str) return '';
  return str
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'")
    .replace(/&amp;/g, '&');
}

function extractTag(block, tag) {
  const re = new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i');
  const m = block.match(re);
  if (!m) return '';
  let val = m[1].trim();
  const cdata = val.match(/^<!\[CDATA\[([\s\S]*?)\]\]>$/);
  if (cdata) val = cdata[1];
  return decodeEntities(stripHtml(val));
}

const httpItems = $input.all();
const sourceItems = $('Build RSS Source List').all();
const candidates = [];
const fetchErrors = [];

for (let i = 0; i < httpItems.length; i++) {
  const source = sourceItems[i] ? sourceItems[i].json : { name: 'Unknown', domain: '' };
  const body = httpItems[i].json;

  const raw = typeof body === 'string'
    ? body
    : (body.data || body.body || '');

  if (!raw || (body && body.error)) {
    fetchErrors.push({
      source: source.name,
      error: (body && (body.error || body.message)) || 'empty response',
    });
    continue;
  }

  const itemBlocks = raw.match(/<item>[\s\S]*?<\/item>/g) || [];

  for (const block of itemBlocks) {
    const title = extractTag(block, 'title');
    const link = extractTag(block, 'link');
    const pubDateStr = extractTag(block, 'pubDate');
    const description = extractTag(block, 'description');
    const pubDate = pubDateStr ? new Date(pubDateStr) : null;

    if (pubDate && pubDate.getTime() < cutoff) continue;
    if (!title || !link) continue;

    const combined = `${title} ${description}`;
    if (!containsAny(combined, AI_TERMS)) continue;

    candidates.push({
      source: source.name,
      domain: source.domain,
      title,
      link,
      publishedAt: pubDate ? pubDate.toISOString() : null,
      snippet: description,
    });
  }
}

return [{ json: { candidates, fetchErrors } }];

// ===== Dedupe Exact =====
function normalizeTitle(t) {
  return (t || '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

const input = $input.first().json;
const candidates = input.candidates || [];

const seenLinks = new Set();
const seenTitles = new Set();
const unique = [];

for (const c of candidates) {
  const link = (c.link || '').split('?')[0].replace(/\/$/, '');
  const normTitle = normalizeTitle(c.title);

  if (seenLinks.has(link) || seenTitles.has(normTitle)) continue;
  seenLinks.add(link);
  seenTitles.add(normTitle);
  unique.push(c);
}

return [{ json: { candidates: unique } }];

const config = $('Set Configuration Fields').first().json;
const rawCandidates = $input.first().json.candidates || [];
const candidates = rawCandidates.map((c, idx) => ({
  id: idx,
  source: c.source,
  title: c.title,
  link: c.link,
  publishedAt: c.publishedAt,
  snippet: c.snippet,
}));

const systemPrompt = `You are a research analyst curating a daily digest for a payments company's competitive intelligence team.

You will receive a JSON array of candidate news items already pre-filtered by keyword. Your job:

1. STRICT RELEVANCE FILTER: keep an item only if it is substantively about AI/ML/genAI/agentic AI being APPLIED to fintech or payments (e.g. an AI-powered fraud detection feature, an AI payments agent, an AI underwriting model, a genAI-driven merchant tool, a regulatory stance on AI in payments). REJECT items that only mention "AI" in passing, generic funding/hiring/partnership/security-breach news, unrelated product launches, and pure market-share or financial-results news.
2. SEMANTIC DEDUPE: if two or more items clearly describe the same underlying story or announcement (even from different sources or with different wording), merge them into a single entry. Pick the most authoritative/original source as primary and list any others as "alsoCoveredBy".
3. SUMMARIZE: write a single crisp sentence (<= 30 words) explaining what is newsworthy about each surviving item.

Return ONLY valid JSON (no markdown fences, no commentary) matching this shape:
{"articles": [{"title": string, "link": string, "source": string, "alsoCoveredBy": string[], "publishedAt": string|null, "summary": string}]}

If nothing survives the filter, return {"articles": []}.`;

const userPrompt = `Candidate articles (JSON):\n${JSON.stringify(candidates, null, 2)}`;

return [{
  json: {
    model: config.openaiModel || 'gpt-4o',
    system: systemPrompt,
    userPrompt,
  },
}];

// ===== Parse OpenAI Output & Build Email =====

const config = $('Set Configuration Fields').first().json;
const response = $input.first().json;

// OpenAI Chat Completions returns the answer at choices[0].message.content.
let text = '';
try {
  text = (response.choices && response.choices[0] && response.choices[0].message
    && response.choices[0].message.content) || '';
  text = text.trim();
} catch (e) {
  text = '';
}

// The model is instructed to return raw JSON, but strip code fences defensively.
text = text.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = { articles: [], _parseError: true, _raw: text };
}

const articles = parsed.articles || [];

function esc(s) {
  return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const todayStr = new Date().toLocaleDateString('en-IN', { day: '2-digit', month: 'long', year: 'numeric' });

let rowsHtml = '';
for (const a of articles) {
  const also = (a.alsoCoveredBy && a.alsoCoveredBy.length)
    ? ` <span style="color:#888;">(also: ${esc(a.alsoCoveredBy.join(', '))})</span>`
    : '';
  rowsHtml += `
    <tr>
      <td style="padding:12px 8px;border-bottom:1px solid #eee;vertical-align:top;">
        <div style="font-weight:600;font-size:15px;margin-bottom:4px;">
          <a href="${esc(a.link)}" style="color:#1a56db;text-decoration:none;">${esc(a.title)}</a>
        </div>
        <div style="font-size:13px;color:#555;margin-bottom:4px;">${esc(a.summary)}</div>
        <div style="font-size:12px;color:#999;">Source: ${esc(a.source)}${also}</div>
      </td>
    </tr>`;
}

const bodyHtml = articles.length
  ? `<table style="width:100%;border-collapse:collapse;font-family:Arial,Helvetica,sans-serif;">${rowsHtml}</table>`
  : `<p style="font-family:Arial,Helvetica,sans-serif;color:#555;">No new AI-in-fintech/payments articles from tracked sources in the last ${config.lookbackHours || 30} hours.</p>`;

const html = `
<div style="font-family:Arial,Helvetica,sans-serif;max-width:640px;margin:0 auto;">
  <h2 style="margin-bottom:4px;">${esc(config.fromLabel || 'AI in Fintech Watch')}</h2>
  <div style="color:#777;font-size:13px;margin-bottom:16px;">${todayStr} &middot; Tracking: Razorpay, Stripe, PayU, BillDesk, PhonePe, PayPal, NPCI, RBI</div>
  ${bodyHtml}
  <div style="color:#aaa;font-size:11px;margin-top:24px;">Automated digest &mdash; sources are keyword-filtered and AI-classified, verify before sharing externally.</div>
</div>`;

return [{
  json: {
    articleCount: articles.length,
    subject: `AI in Fintech/Payments Digest — ${todayStr} (${articles.length} article${articles.length === 1 ? '' : 's'})`,
    html,
    recipients: config.recipients,
    _parseError: parsed._parseError || false,
  },
}];
